import test from 'node:test';
import assert from 'node:assert/strict';
import { rotate } from '../src/rotate.js';

const cases = [
  { name: 'zero steps', input: [1, 2, 3, 4], k: 0, expected: [1, 2, 3, 4] },
  { name: 'one step right', input: [1, 2, 3, 4], k: 1, expected: [4, 1, 2, 3] },
  { name: 'two steps right', input: [1, 2, 3, 4], k: 2, expected: [3, 4, 1, 2] },
  { name: 'three steps right', input: [1, 2, 3, 4], k: 3, expected: [2, 3, 4, 1] },
  { name: 'one full rotation', input: [1, 2, 3, 4], k: 4, expected: [1, 2, 3, 4] },
  { name: 'steps exceeding the length', input: [1, 2, 3, 4], k: 6, expected: [3, 4, 1, 2] },
  { name: 'empty array with zero steps', input: [], k: 0, expected: [] },
  { name: 'empty array with positive steps', input: [], k: 7, expected: [] },
  { name: 'singleton with zero steps', input: [9], k: 0, expected: [9] },
  { name: 'singleton with positive steps', input: [9], k: 7, expected: [9] },
];

for (const { name, input, k, expected } of cases) {
  test(`rotate returns a new array and preserves input: ${name}`, () => {
    const original = input.slice();
    const result = rotate(input, k);

    assert.ok(Array.isArray(result));
    assert.notStrictEqual(result, input);
    assert.deepStrictEqual(result, expected);
    assert.deepStrictEqual(input, original);
  });
}

test('rotate accepts frozen input without mutating it', () => {
  const input = Object.freeze([1, 2, 3, 4]);
  const result = rotate(input, 1);

  assert.ok(Array.isArray(result));
  assert.notStrictEqual(result, input);
  assert.deepStrictEqual(result, [4, 1, 2, 3]);
  assert.deepStrictEqual(input, [1, 2, 3, 4]);
});

const nonArrays = [
  { name: 'null', value: null },
  { name: 'undefined', value: undefined },
  { name: 'string', value: 'abcd' },
  { name: 'number', value: 42 },
  { name: 'array-like object', value: { 0: 'a', 1: 'b', length: 2 } },
];

for (const { name, value } of nonArrays) {
  test(`rotate rejects ${name} with TypeError`, () => {
    assert.throws(() => rotate(value, 0), TypeError);
    assert.throws(() => rotate(value, 1), TypeError);
  });
}

for (const k of [-1, -4, 0.5, 1.5, -0.5]) {
  test(`rotate rejects step count ${k} on a nonempty array`, () => {
    const input = [1, 2, 3, 4];

    assert.throws(() => rotate(input, k), RangeError);
    assert.deepStrictEqual(input, [1, 2, 3, 4]);
  });

  test(`rotate rejects step count ${k} on an empty array`, () => {
    const input = [];

    assert.throws(() => rotate(input, k), RangeError);
    assert.deepStrictEqual(input, []);
  });
}

